using System;using System.Drawing;using System.Drawing.Imaging;using System.Runtime.InteropServices;using System.Text;using System.Web.Script.Serialization;using System.Collections.Generic;
class ShellThumbnail {
  [StructLayout(LayoutKind.Sequential)]struct SIZE { public int cx;public int cy;public SIZE(int w,int h){cx=w;cy=h;} }
  [ComImport,Guid("bcc18b79-ba16-442f-80c4-8a59c30c463b"),InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]interface IImageFactory { [PreserveSig]int GetImage(SIZE size,uint flags,out IntPtr bitmap); }
  [DllImport("shell32.dll",CharSet=CharSet.Unicode,PreserveSig=true)]static extern int SHCreateItemFromParsingName(string path,IntPtr binding,ref Guid iid,[MarshalAs(UnmanagedType.Interface)]out IImageFactory item);
  [DllImport("gdi32.dll")]static extern bool DeleteObject(IntPtr bitmap);
  [STAThread]static void Main(){Console.InputEncoding=new UTF8Encoding(false);Console.OutputEncoding=new UTF8Encoding(false);var json=new JavaScriptSerializer();string line;while((line=Console.ReadLine())!=null){var response=new Dictionary<string,object>();IImageFactory factory=null;IntPtr bitmap=IntPtr.Zero;try{var input=json.Deserialize<Dictionary<string,object>>(line);response["id"]=input["id"];Guid iid=new Guid("bcc18b79-ba16-442f-80c4-8a59c30c463b");int hr=SHCreateItemFromParsingName((string)input["filename"],IntPtr.Zero,ref iid,out factory);if(hr!=0)Marshal.ThrowExceptionForHR(hr);hr=factory.GetImage(new SIZE(480,320),0x08,out bitmap);if(hr!=0||bitmap==IntPtr.Zero)throw new Exception("No system content thumbnail");using(var image=Image.FromHbitmap(bitmap)){image.Save((string)input["output"],ImageFormat.Png);}response["ok"]=true;}catch(Exception e){response["ok"]=false;response["error"]=e.Message;}finally{if(bitmap!=IntPtr.Zero)DeleteObject(bitmap);if(factory!=null)Marshal.ReleaseComObject(factory);}Console.WriteLine(json.Serialize(response));Console.Out.Flush();}}
}
